<template><div class="shell"><aside class="sidebar" :class="{collapsed}"><div class="brand"><div class="brand-icon"><PackageOpen :size="20"/></div><span v-if="!collapsed">nexstock</span><button class="collapse" @click="collapsed=!collapsed"><PanelLeftClose :size="17"/></button></div><div v-if="!collapsed" class="workspace"><div class="workspace-logo">A</div><div><b>Acme Corporation</b><small>Enterprise plan</small></div><ChevronDown :size="15" class="muted"/></div><div class="nav-label" v-if="!collapsed">WORKSPACE</div><nav><RouterLink to="/" :title="collapsed?'Overview':''"><LayoutDashboard/><span v-if="!collapsed">Overview</span></RouterLink><RouterLink v-for="item in mainNav" :key="item.path" :to="item.path" :title="collapsed?item.name:''"><component :is="item.icon"/><span v-if="!collapsed">{{item.name}}</span></RouterLink><div class="nav-label" v-if="!collapsed">MANAGE</div><RouterLink v-for="item in manageNav" :key="item.path" :to="item.path" :title="collapsed?item.name:''"><component :is="item.icon"/><span v-if="!collapsed">{{item.name}}</span></RouterLink></nav><div class="sidebar-bottom"><div class="help-card" v-if="!collapsed"><div class="help-icon"><LifeBuoy :size="16"/></div><b>Need a hand?</b><p>Visit our help center for tips and guides.</p><a href="mailto:support@nexstock.example">Open help center <ArrowUpRight :size="13"/></a></div><button class="profile" @click="logout"><div class="avatar">JD</div><div v-if="!collapsed" class="profile-info"><b>{{user.name||'Jordan Davis'}}</b><small>{{user.role||'Administrator'}} Â· Sign out</small></div><LogOut v-if="!collapsed" class="muted" :size="16"/></button></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><span>Workspace</span><ChevronRight :size="15"/><b>{{title}}</b></div><div class="top-actions"><button class="icon-button" title="Search"><Search :size="18"/></button><button class="icon-button notification" title="Notifications" @click="router.push('/notifications')"><Bell :size="18"/><i></i></button><div class="top-divider"></div><button class="date-button"><CalendarDays :size="16"/> Last 30 days <ChevronDown :size="14"/></button></div></header><section class="page"><RouterView/></section></main><Transition><div v-if="toast" class="live-toast"><span class="live-toast-dot"></span>{{toast}}</div></Transition></div></template>
<script setup lang="ts">import {computed,ref,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {HubConnectionBuilder,LogLevel} from '@microsoft/signalr';import {PackageOpen,PanelLeftClose,ChevronDown,LayoutDashboard,Boxes,ShoppingCart,ClipboardList,Truck,Users,Warehouse,ChartNoAxesCombined,Settings,LifeBuoy,ArrowUpRight,ChevronRight,Search,Bell,CalendarDays,Package,LogOut} from 'lucide-vue-next';const collapsed=ref(false),route=useRoute(),router=useRouter(),toast=ref(''),user=JSON.parse(localStorage.getItem('nexstock_user')||'{}');let timer:number|undefined;const title=computed(()=>String(route.meta.title||route.params.section||'Overview').replace(/^./,s=>s.toUpperCase()));const mainNav=[{name:'Products',path:'/products',icon:Package},{name:'Inventory',path:'/inventory',icon:Boxes},{name:'Orders',path:'/orders',icon:ShoppingCart},{name:'Purchases',path:'/purchases',icon:ClipboardList}];const manageNav=[{name:'Suppliers',path:'/suppliers',icon:Truck},{name:'Customers',path:'/customers',icon:Users},{name:'Warehouses',path:'/warehouses',icon:Warehouse},{name:'Reports',path:'/reports',icon:ChartNoAxesCombined},{name:'Users',path:'/users',icon:Settings},{name:'Notifications',path:'/notifications',icon:Bell}];function logout(){localStorage.removeItem('nexstock_token');localStorage.removeItem('nexstock_user');router.push('/login');}let connection:any;onMounted(async()=>{connection=new HubConnectionBuilder().withUrl(import.meta.env.VITE_SIGNALR_URL||'http://localhost:8081/hubs/notifications',{accessTokenFactory:()=>localStorage.getItem('nexstock_token')||''}).withAutomaticReconnect().configureLogging(LogLevel.Error).build();const notify=(message:string)=>{toast.value=message;window.dispatchEvent(new CustomEvent('nexstock-update'));window.clearTimeout(timer);timer=window.setTimeout(()=>toast.value='',4500);};connection.on('InventoryUpdated',()=>notify('Inventory updated'));connection.on('LowStock',(x:any)=>notify(`Low stock: ${x.product} has ${x.stock} units`));connection.on('OrderCreated',(x:any)=>notify(`New order ${x.number}`));connection.on('PurchaseUpdated',()=>notify('Purchase order updated'));try{await connection.start();}catch{console.info('Live notifications will reconnect when the API is available.');}});onBeforeUnmount(()=>{connection?.stop();window.clearTimeout(timer);});</script>
